begin;
select no_plan();
select ok(not has_function_privilege('authenticated','private.part_two_owner_delete_lock()','execute'),'owner deletion lifecycle trigger is not a customer callable bypass');
select ok(exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='auth' and c.relname='users' and t.tgname='part_two_owner_delete_lock' and (t.tgtype&1)=0 and (t.tgtype&2)=2),'owner deletion acquires lifecycle fence at statement BEFORE user row locks');
select ok(position('pg_advisory_xact_lock(40203)' in pg_get_functiondef('private.part_one_owner()'::regprocedure))<position('hashtextextended' in pg_get_functiondef('private.part_one_owner()'::regprocedure)),'Part1 owner initialization acquires globals before per-owner lock');
select ok(position('pg_advisory_xact_lock(40203)' in pg_get_functiondef('public.part_two_worker(text,jsonb)'::regprocedure))<position('select * into cur' in pg_get_functiondef('public.part_two_worker(text,jsonb)'::regprocedure)),'every Part2 worker action acquires lifecycle fence before current/owner rows');
select ok(position('pg_advisory_xact_lock(40203)' in pg_get_functiondef('public.part_two_operation(text,jsonb)'::regprocedure))<position('private.part_one_owner()' in pg_get_functiondef('public.part_two_operation(text,jsonb)'::regprocedure)),'Part2 requests acquire globals before owner/current rows');
insert into auth.users(id,email,is_anonymous,raw_user_meta_data) values ('fc000000-0000-4000-8000-000000000001',null,true,'{}');
insert into private.part_one_records(id,kind,item_id,revision,policy_id,policy_version,payload,observed_at,expires_at) values ('fc100000-0000-4000-8000-000000000001','snapshot','fc200000-0000-4000-8000-000000000001',1,'derive_catalog','1','{"name":"Independent original synthetic public identity"}',now(),now()+interval '1 day');
insert into private.part_one_scans(id,owner_id,idempotency_key,request,generation,result) values ('fc300000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','auth-saved-public','{}',0,'{}');
insert into private.part_one_saves(id,owner_id,idempotency_key,scan_id,snapshot_at_save_id,saved_result,saved_request) values ('fc400000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','saved-public-auth','fc300000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001','{}','{}');
insert into private.part_two_current(binding_key,owner_id,scan_id,result_revision,generation,evidence_revision,deletion_epoch,dependencies) values ('owner-delete-current','fc000000-0000-4000-8000-000000000001','fc300000-0000-4000-8000-000000000001',2,0,1,0,array['fc100000-0000-4000-8000-000000000001'::uuid]);
insert into private.part_two_releases(id,versions,release_hash,permitted,review_evidence) values ('owner-delete-test-release','{}',repeat('c',64),true,'Original synthetic local fixture only');
insert into private.part_two_snapshots(id,binding_key,owner_id,build_key,result_revision,release_id,payload,dependencies,private_payload,expires_at) values ('fc500000-0000-4000-8000-000000000001','owner-delete-current','fc000000-0000-4000-8000-000000000001','owner-delete-build',2,'owner-delete-test-release','{"state":"ready"}',array['fc100000-0000-4000-8000-000000000001'::uuid],false,now()+interval '1 hour');
insert into private.part_two_saves(save_id,owner_id,snapshot_id,binding_key,result_revision,snapshot_at_save_id,saved_versions) values ('fc400000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','fc500000-0000-4000-8000-000000000001','owner-delete-current',2,'fc500000-0000-4000-8000-000000000001','{}');
delete from auth.users where id='fc000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from private.part_one_saves where owner_id='fc000000-0000-4000-8000-000000000001'),0,'Owner deletion directly cascades public saved Part1 records without pre-deleting saves');
select is((select count(*)::integer from private.part_two_snapshots where owner_id='fc000000-0000-4000-8000-000000000001'),0,'Owner deletion removes owner-derived saved payload copies');
select is((select count(*)::integer from private.part_two_current where owner_id='fc000000-0000-4000-8000-000000000001'),0,'Owner deletion removes owner work/cache rows');
select is((select count(*)::integer from private.part_two_saves where owner_id='fc000000-0000-4000-8000-000000000001'),0,'Owner deletion removes interpretation pin links');
select is((select count(*)::integer from private.part_one_records where id='fc100000-0000-4000-8000-000000000001'),1,'independently permitted public evidence survives owner deletion');
select finish();
rollback;
